  const title=t+" مكتوبة كاملة مع عداد"+(n?" — "+AR(n)+" ذكرًا":"")+" | وِرد";
  const desc=t+" مكتوبة كاملة بالتشكيل"+(n?" ("+AR(n)+" ذكرًا)":"")+" مع عدّاد لكل ذكر، وعدد مرات قوله ومصدره من القرآن والسنة."+(WHEN[slug]?" وقتها "+WHEN[slug]:"")+" تعمل دون إنترنت.";
