    if(!/^[A-Za-z0-9_-]{80,100}$/.test(keys.p256dh)||!/^[A-Za-z0-9_-]{16,32}$/.test(keys.auth))return json({error:"keys"},400);
    const exists=await env.DB.prepare("SELECT 1 FROM subs WHERE id=?").bind(id).first();if(!exists){if(!rl("new"+ip,3))return json({error:"rate"},429);const cnt=await env.DB.prepare("SELECT count(*) AS c FROM subs").first("c");if(cnt>20000)return json({error:"full"},503)}
    const now=Date.now(),ev=(Array.isArray(b.events)?b.events:[]).filter(e=>e&&+e.t>now-60000&&+e.t<now+40*864e5).slice(0,400);
    const st=[env.DB.prepare("INSERT INTO subs(id,endpoint,p256dh,auth,created,updated) VALUES(?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET p256dh=excluded.p256dh,auth=excluded.auth,updated=excluded.updated").bind(id,ep,clip(keys.p256dh,200),clip(keys.auth,60),now,now),env.DB.prepare("DELETE FROM ev WHERE sid=?").bind(id)];
    const ins=env.DB.prepare("INSERT INTO ev(sid,t,title,body,tag,url) VALUES(?,?,?,?,?,?)");
